BEGIN TRANSACTION;
CREATE TABLE approved_chains(code TEXT PRIMARY KEY REFERENCES chains(code), name TEXT NOT NULL, format TEXT NOT NULL CHECK(format IN ("supermarket","discount_supermarket","hypermarket")), source TEXT NOT NULL, checked_date TEXT NOT NULL);
CREATE TABLE chain_prices (
    chain TEXT NOT NULL REFERENCES chains(code),
    product_id INTEGER NOT NULL REFERENCES products(id),
    package_price_ore INTEGER NOT NULL CHECK(package_price_ore>0),
    unit_price_ore REAL NOT NULL CHECK(unit_price_ore>0),
    method TEXT NOT NULL,
    basis TEXT NOT NULL,
    source TEXT NOT NULL,
    date TEXT NOT NULL,
    PRIMARY KEY(chain,product_id)
);
CREATE TABLE chains (
    code TEXT PRIMARY KEY,
    name TEXT NOT NULL
);
CREATE TABLE fallback_prices (
    ingredient_id INTEGER PRIMARY KEY REFERENCES ingredient_keys(id),
    product_id INTEGER NOT NULL REFERENCES products(id),
    package_price_ore INTEGER NOT NULL CHECK(package_price_ore>0),
    unit_price_ore REAL NOT NULL CHECK(unit_price_ore>0),
    method TEXT NOT NULL,
    basis TEXT NOT NULL,
    source TEXT NOT NULL,
    date TEXT NOT NULL
);
CREATE TABLE ingredient_keys (
    id INTEGER PRIMARY KEY,
    name TEXT NOT NULL,
    unit TEXT NOT NULL CHECK(unit IN ('g','ml','pcs'))
);
CREATE TABLE metadata (name TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE products (
    id INTEGER PRIMARY KEY,
    ingredient_id INTEGER NOT NULL REFERENCES ingredient_keys(id),
    name TEXT NOT NULL,
    package_amount REAL NOT NULL CHECK(package_amount>0),
    unit TEXT NOT NULL CHECK(unit IN ('g','ml','pcs')),
    source_product_id INTEGER,
    basis TEXT NOT NULL
);
CREATE TABLE store_approvals(store_id INTEGER PRIMARY KEY REFERENCES stores(id), chain TEXT NOT NULL REFERENCES approved_chains(code), format TEXT NOT NULL CHECK(format IN ("supermarket","discount_supermarket","hypermarket")), official_source_id TEXT NOT NULL, source TEXT NOT NULL, checked_date TEXT NOT NULL);
CREATE TABLE store_prices (
    store_id INTEGER NOT NULL REFERENCES stores(id),
    product_id INTEGER NOT NULL REFERENCES products(id),
    package_price_ore INTEGER NOT NULL CHECK(package_price_ore>0),
    unit_price_ore REAL NOT NULL CHECK(unit_price_ore>0),
    method TEXT NOT NULL,
    basis TEXT NOT NULL,
    source TEXT NOT NULL,
    date TEXT NOT NULL,
    PRIMARY KEY(store_id,product_id)
);
CREATE TABLE store_sources (
    store_id INTEGER NOT NULL REFERENCES stores(id),
    source TEXT NOT NULL,
    source_id TEXT NOT NULL,
    source_date TEXT NOT NULL,
    retrieved_date TEXT NOT NULL,
    basis TEXT NOT NULL,
    PRIMARY KEY(store_id,source,source_id)
);
CREATE TABLE stores (
    id INTEGER PRIMARY KEY,
    osm_id TEXT UNIQUE,
    chain TEXT REFERENCES chains(code),
    name TEXT NOT NULL,
    address TEXT NOT NULL,
    postal_code TEXT NOT NULL,
    city TEXT NOT NULL,
    latitude REAL NOT NULL CHECK(latitude BETWEEN 54 AND 58),
    longitude REAL NOT NULL CHECK(longitude BETWEEN 7 AND 16),
    x REAL NOT NULL CHECK(x BETWEEN 100000 AND 900000),
    y REAL NOT NULL CHECK(y BETWEEN 6000000 AND 6600000),
    source TEXT NOT NULL,
    checked_date TEXT NOT NULL
);
CREATE INDEX index_1 ON products(ingredient_id);
CREATE INDEX index_2 ON chain_prices(product_id,chain);
CREATE INDEX index_3 ON store_prices(product_id,store_id);
CREATE INDEX index_4 ON stores(chain);
COMMIT;
